from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
OUT=HERE.parent
fixtures=json.loads((HERE/'fixtures.json').read_text())
titles=['เสียงตอบบนราวศาลา','ห้าทางช่วยพี่ก้าม','R5 · ตั้งหลักก่อนกระซิบ','R5 · แสงเปลี่ยนข้าง','แคมป์ใต้ชายคา','แคมป์ในมือเดียว','หนึ่งฝีเข็มที่เย็บแล้ว','เคาะราวในคืนไฟดับ','ทางเลือกในแสงแรก','สามทางบนมือถือ','R4A · ถาดครบสิบหกใบ','R2 · โถงประตูน้ำ','บ้านยังมีคนรอรับ']
notes=['เจ้ากบยืนบนราว เตื๊อกคุกเข่า ลำไฟฉายตัดฝนเหนือคลองมืด ตำแหน่งสายตาใกล้ left 28% และ right 72%','การ์ดครบห้าข้อตาม A2A-05 ป้ายท่าผสานและทักษะครอบครัว พร้อมราคาเป็นเม็ด ไม่มีแถบนำซ้ำ','เทิร์น 1 แสง 4 กระซิบฝันร้ายยังมีผล กระเป๋าไม่มีริบบิ้น ท่าปิดศึกยังไม่ปรากฏ','เทิร์น 3 แสง 6 หลังโล่พี่ก้ามและตั้งสติฟังฝน ป้ายซ้ำครบห้าการ์ด มีท่าปิดศึก แต่เงายังไม่มีผ้าคลุม','กิจกรรมครบแปดใบ ดามข้อเท้าใช้สนับไปแล้ว เตื๊อกมีเฝือกเปลือกไม้ พี่ก้ามไม่ถือเฟือง','ถาด 2 × 4 ใบละ 72 px เหลือสองรอบลาน ปุ่มเดินทางยังจาง','ฝีแรกเป็นด้ายขาวบนผ้า สองจุดทองที่เหลือมองเห็น 30 px และรับสัมผัส 44 px','เมืองมืดทุกหน้าต่าง ตะเกียงหนึ่งดวงกับไฟฉาย มืออยู่บนราวไม้เปียก','เปี๊ยกหลับใต้ผ้าห่ม เจ้ากบยืนบนโต๊ะ สหายสี่ตัวมองจากขอบหน้าต่าง เกลียวแต่ละทางต่างความหมาย','E-HOME และ E-POND เปิด E-DAWN ยังขาดการยืนหยัดเอง ข้อความเงื่อนไขตรงบท','แท็บของ·ผสานเปิด เมล็ด เฟือง กระดุม ริบบิ้น และผ้าพันคอนำลม อีกสิบเอ็ดการ์ดเข้าถึงผ่านท่าหลักและสองแท็บ','เทิร์น 2 แสง 4 หลังตั้งสติฟังฝน ครอบครัวสามใบมีซ้ำ ของสามใบกับท่าผสานสองใบปรากฏ','สถานะไม่มีฉากจบผ่าน E-POND เปิดด้วย Safety Fallback พร้อมเกลียวที่สี่และคำว่า พี่กับจะแบกกลับเอง']
rows=[]
for s in fixtures['screens']:
 r=json.loads((OUT/'evidence'/('screen-'+str(s['id']).zfill(2)+'.json')).read_text())
 state=s['clash']
 stamp=(state['round']+' · เทิร์น '+str(state['turn'])+' · แสง '+str(state['light'])) if state else ['A3-08','A2A-05','','','A3-12 · C3','A3-12 · C3','MA-5','MA-3','A5-11','A5-11','','','A5-11 · Fallback'][s['id']-1]
 rows.append({'id':s['id'],'stem':s['stem'],'mobile':s['mobile'],'title':titles[s['id']-1],'state':stamp,'note':notes[s['id']-1],'proof':'Sarabun · เป้ากดอย่างน้อย 44 px · ไม่มีข้อความล้นหรือ UI ล้ำแถบใบหน้า','v2':s['id']<=10,'bounds':r['componentBounds'],'width':r['viewport']['width'],'height':r['viewport']['height']})
text=(HERE/'review-template.html').read_text().replace('__REVIEW_DATA__',json.dumps(rows,ensure_ascii=False))
(OUT.parents[1]/'evidence/ux-mockups-v3-review.html').write_text(text)
print('Review generated with 13 captured geometry records')
